import {
  ExecutionTraceSource,
  type ExecutionTraceSourceOptions,
} from '../intake/execution-trace-source.js';

import {
  evaluateTrace,
  type EvaluateTraceOptions,
  type EvaluateTraceResult,
} from './evaluate-trace.js';

export interface EvaluateExecutionTraceOptions
  extends EvaluateTraceOptions, ExecutionTraceSourceOptions {}

/**
 * Evaluate an existing trace generated by Execution Core.
 *
 * Execution Core owns the trace file.
 * HEAE reads it without modifying the original.
 */
export async function evaluateExecutionTrace(
  runId: string,
  taskId: string,
  options: EvaluateExecutionTraceOptions = {},
): Promise<EvaluateTraceResult> {
  const source = new ExecutionTraceSource({
    tracesDirectory: options.tracesDirectory,
  });

  const spans = await source.read(runId, taskId);

  // Pass the validated spans to HEAE's existing
  // JSONL evaluation pipeline.
  const jsonlContent = spans.map((span) => JSON.stringify(span)).join('\n');

  return evaluateTrace(jsonlContent, {
    provider: options.provider,
    model: options.model,
    store: options.store,
    graphStore: options.graphStore,
    recovery: options.recovery,
  });
}
